    (hΘ : S.H.transpose * B.transpose * B * S.H
      = S'.H.transpose * B'.transpose * B' * S'.H) :
    B.transpose * B = (B' * M).transpose * (B' * M)

theorem gram_identity_conj (S S' : Solution d p K) {M : Matrix (Fin d) (Fin d) ℝ}
