    let U := 12 / (5 * ρ)
    (2 / U) * (∫ t in (0 : ℝ)..U0,
      ‖prawitzKernel (t / U)‖ * prawitzDiscrepancyEnvelope ρ t) ≤ ρ / 4

theorem prawitz_budget_low
