theorem tendsto_map_mul_of_tendsto {ι : Type*} {l : Filter ι}
    {νs : ι → ProbabilityMeasure ℝ} {ν : ProbabilityMeasure ℝ}
    {a : ι → ℝ} {a₀ : ℝ}
    (hν : Tendsto νs l (𝓝 ν)) (ha : Tendsto a l (𝓝 a₀)) :
    Tendsto
      (fun i => (νs i).map ((measurable_const.mul measurable_id).aemeasurable :
        AEMeasurable (fun x : ℝ => a i * x) (νs i : Measure ℝ)))
      l
      (𝓝 (ν.map ((measurable_const.mul measurable_id).aemeasurable :
        AEMeasurable (fun x : ℝ => a₀ * x) (ν : Measure ℝ))))

theorem abs_covariance_le_sqrt_mul [IsFiniteMeasure μ] {X Y : Ω → ℝ}
    (hX : MemLp X 2 μ) (hY : MemLp Y 2 μ) :
    |covariance X Y μ| ≤ Real.sqrt (variance X μ) * Real.sqrt (variance Y μ)

theorem covariance_sq_le_variance_mul [IsFiniteMeasure μ] {X Y : Ω → ℝ}
    (hX : MemLp X 2 μ) (hY : MemLp Y 2 μ) :
    covariance X Y μ ^ 2 ≤ variance X μ * variance Y μ

lemma eventCondExp_congr_ae (μ : Measure Ω) (A : Set Ω) {f g : Ω → ℝ}
    (h : f =ᵐ[μ.restrict A] g) :
