lemma condQuantileSet_up_closed {ρ : Measure (α × ℝ)} {τ : α → ℝ} {a : α}
    {x x' : ℝ} (hx : x ∈ {y : ℝ | τ a ≤ condCDF ρ a y}) (hxx' : x ≤ x') :
    x' ∈ {y : ℝ | τ a ≤ condCDF ρ a y}

lemma condQuantile_le_iff {ρ : Measure (α × ℝ)} {τ : α → ℝ} {a : α}
    {x : ℝ} (hτ0 : 0 < τ a) (hτ1 : τ a < 1) :
    condQuantile ρ τ a ≤ x ↔ τ a ≤ condCDF ρ a x

lemma condQuantile_le_of_le_condCDF {ρ : Measure (α × ℝ)} {τ : α → ℝ}
    {a : α} {x : ℝ} (hτ0 : 0 < τ a) (hx : τ a ≤ condCDF ρ a x) :
    condQuantile ρ τ a ≤ x

lemma le_condCDF_of_condQuantile_le {ρ : Measure (α × ℝ)} {τ : α → ℝ}
    {a : α} {x : ℝ} (hτ1 : τ a < 1) (hx : condQuantile ρ τ a ≤ x) :
    τ a ≤ condCDF ρ a x

theorem FiniteDyadicTraversal.truncate_trans {d l m n : ℕ}
    (T : FiniteDyadicTraversal d n) (hlm : l ≤ m) (hmn : m ≤ n) :
    (T.truncate hmn).truncate hlm = T.truncate (hlm.trans hmn)

theorem LocalizedCubeMap.continuousOn {d : ℕ} {T : DyadicTraversal d}
    (H : LocalizedCubeMap d T) (hd : 2 ≤ d) :
    ContinuousOn H.toFun (Set.Icc (0 : ℝ) 1)

theorem LocalizedCubeMap.mapsToCube {d : ℕ} {T : DyadicTraversal d}
    (H : LocalizedCubeMap d T) {t : ℝ} (ht : t ∈ Set.Icc (0 : ℝ) 1) :
    InUnitCube (H.toFun t)

theorem LocalizedCubeMap.modulus {d : ℕ} {T : DyadicTraversal d}
    (H : LocalizedCubeMap d T) (hd : 2 ≤ d) {s t : ℝ}
    (hs : s ∈ Set.Icc (0 : ℝ) 1) (ht : t ∈ Set.Icc (0 : ℝ) 1) :
    sqEuclideanDist (H.toFun s) (H.toFun t) ≤
      16 * (d : ℝ) * |s - t| ^ ((2 : ℝ) / d)

theorem LocalizedCubeMap.surjectiveOn {d : ℕ} {T : DyadicTraversal d}
    (H : LocalizedCubeMap d T) (x : Fin d → ℝ) (hx : InUnitCube x) :
    ∃ t : ℝ, t ∈ Set.Icc (0 : ℝ) 1 ∧ H.toFun t = x

lemma continuous_uniformOnFun_affine_of_compact
    {α E : Type*} [TopologicalSpace α] [NormedAddCommGroup E] [NormedSpace ℝ E]
    {K : Set α} (hK : IsCompact K) (hKne : K.Nonempty) {f g : α → E}
    (hf : ContinuousOn f K) (hg : ContinuousOn g K) :
    Continuous (fun t : ℝ => UniformOnFun.ofFun {K}
      (fun x => (1 - t) • f x + t • g x))

