lemma sampleMean_sub_ge_setEq (S : IIDSample Ω X μ P) (f : X → ℝ) (m : ℝ)
    {n : ℕ} (hn : 0 < n) (ε : ℝ) :
    {ω | ε ≤ S.sampleMean f n ω - m}
      = {ω | (n : ℝ) * ε ≤ ∑ i ∈ Finset.range n, (f (S.Z i ω) - m)}

lemma IIDSample.integral_comp_eq (S : IIDSample Ω X μ P) {f : X → ℝ}
    (hf : AEMeasurable f P) (i : ℕ) :
    ∫ ω, f (S.Z i ω) ∂μ = ∫ x, f x ∂P

theorem generalizedContrastVariance_eq_inv_constrainedInformation {I : Matrix ι ι ℝ}
    (hI : I.PosSemidef) {c : ι → ℝ} (hc : c ≠ 0) :
    generalizedContrastVariance I c = (ENNReal.ofReal (constrainedInformation I c))⁻¹

theorem generalizedContrastVariance_eq_top_iff_no_solution {I : Matrix ι ι ℝ}
    (hI : I.PosSemidef) {c : ι → ℝ} (hc : c ≠ 0) :
    generalizedContrastVariance I c = ⊤ ↔ ¬ ∃ v : ι → ℝ, I.mulVec v = c

theorem integral_abs_cdfGap_le_integral_crossingEnvelope {ι κ : Type*}
    [Fintype ι] [Fintype κ] {μ : AtomicLaw ι} {ν : AtomicLaw κ}
    (π : TransportPlan μ ν) :
    (∫ x, |cdfGap μ ν x|) ≤ ∫ x, crossingEnvelope π x

theorem integral_abs_cdfGap_le_transportCost {ι κ : Type*}
    [Fintype ι] [Fintype κ] {μ : AtomicLaw ι} {ν : AtomicLaw κ}
    (hμ : μ.Valid) (hν : ν.Valid) (π : TransportPlan μ ν) :
    (∫ x, |cdfGap μ ν x|) ≤ transportCost π

theorem integral_crossingEnvelope_eq_transportCost {ι κ : Type*}
    [Fintype ι] [Fintype κ] {μ : AtomicLaw ι} {ν : AtomicLaw κ}
    (π : TransportPlan μ ν) :
    (∫ x, crossingEnvelope π x) = transportCost π

theorem lipschitz_integral_sub_le_transportCost {ι κ : Type*}
    [Fintype ι] [Fintype κ] {μ : AtomicLaw ι} {ν : AtomicLaw κ}
    (π : TransportPlan μ ν) (f : ℝ → ℝ) (hf : LipschitzWith 1 f) :
    |μ.integral f - ν.integral f| ≤ transportCost π

